{
  "name": "Velocity Personal Branding",
  "description": "A high-performance personal branding site inspired by Lando Norris, featuring AI-powered image analysis to generate your unique identity.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface BrandProfile {
  name: string;
  tagline: string;
  personality: string;
  primaryColor: string;
  brandAttributes: string[];
  bio: string;
}

export interface BrandingResponse {
  profile: BrandProfile;
}

import { GoogleGenAI, Type } from "@google/genai";
import { BrandProfile } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeBrandingFromImage = async (base64Image: string): Promise<BrandProfile> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image.split(',')[1] || base64Image,
            },
          },
          {
            text: "Analyze this person's style and vibe. Create a high-performance personal branding profile inspired by Lando Norris (fast, modern, youthful, high-tech, neon-accents). Return a JSON object with: name (suggested if not obvious), tagline (short, powerful), personality (2-3 words), primaryColor (hex neon), brandAttributes (list of 4 keywords), and bio (short professional but edgy bio).",
          },
        ],
      },
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          tagline: { type: Type.STRING },
          personality: { type: Type.STRING },
          primaryColor: { type: Type.STRING },
          brandAttributes: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
          },
          bio: { type: Type.STRING },
        },
        required: ["name", "tagline", "personality", "primaryColor", "brandAttributes", "bio"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text);
};

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface Props {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}

export const FadeIn: React.FC<Props> = ({ children, delay = 0, className = "" }) => (
  <motion.div
    initial={{ opacity: 0, y: 20 }}
    whileInView={{ opacity: 1, y: 0 }}
    viewport={{ once: true }}
    transition={{ duration: 0.6, delay, ease: "easeOut" }}
    className={className}
  >
    {children}
  </motion.div>
);

export const SlideIn: React.FC<Props> = ({ children, delay = 0, className = "" }) => (
  <motion.div
    initial={{ x: -100, opacity: 0 }}
    whileInView={{ x: 0, opacity: 1 }}
    viewport={{ once: true }}
    transition={{ duration: 0.8, delay, ease: [0.16, 1, 0.3, 1] }}
    className={className}
  >
    {children}
  </motion.div>
);

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { BrandProfile } from './types';
import { analyzeBrandingFromImage } from './services/geminiService';
import { FadeIn, SlideIn } from './components/MotionWrapper';

const NEON_YELLOW = "#d9ff00";

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [profile, setProfile] = useState<BrandProfile | null>(null);
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setPreviewImage(base64);

      try {
        const result = await analyzeBrandingFromImage(base64);
        setProfile(result);
      } catch (err) {
        console.error(err);
        setError("Não foi possível analisar a imagem. Verifique sua chave de API.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const reset = () => {
    setProfile(null);
    setPreviewImage(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-[#d9ff00] selection:text-black">
      {/* Dynamic Background */}
      <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-[#d9ff00]/10 blur-[120px] rounded-full" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-[#d9ff00]/5 blur-[150px] rounded-full" />
        <div className="absolute top-[20%] right-[10%] w-[1px] h-[60%] bg-gradient-to-b from-transparent via-[#d9ff00]/20 to-transparent" />
      </div>

      {/* Navigation */}
      <nav className="fixed top-0 left-0 w-full z-50 px-6 py-4 flex justify-between items-center bg-[#050505]/80 backdrop-blur-md border-b border-white/5">
        <div className="font-oswald text-2xl tracking-tighter flex items-center gap-1 group cursor-pointer" onClick={reset}>
          <span className="bg-[#d9ff00] text-black px-2 py-0.5 transform -skew-x-12 group-hover:skew-x-0 transition-transform">VELO</span>
          <span>BRAND</span>
        </div>
        <div className="hidden md:flex gap-8 font-medium text-sm tracking-widest uppercase">
          <a href="#" className="hover:text-[#d9ff00] transition-colors">Racing</a>
          <a href="#" className="hover:text-[#d9ff00] transition-colors">Lifestyle</a>
          <a href="#" className="hover:text-[#d9ff00] transition-colors">Performance</a>
        </div>
        <button 
          onClick={() => fileInputRef.current?.click()}
          className="bg-white text-black font-oswald px-6 py-2 uppercase tracking-widest text-sm hover:bg-[#d9ff00] transition-all transform hover:-translate-y-1 active:translate-y-0"
        >
          {profile ? "New Profile" : "Get Started"}
        </button>
      </nav>

      {/* Main Content */}
      <main className="relative z-10 pt-32 pb-20 px-6 max-w-7xl mx-auto">
        <AnimatePresence mode="wait">
          {!profile && !loading ? (
            <motion.section 
              key="hero"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0, y: -20 }}
              className="min-h-[70vh] flex flex-col items-center justify-center text-center"
            >
              <SlideIn>
                <h1 className="font-oswald text-6xl md:text-9xl uppercase leading-[0.9] tracking-tighter mb-8">
                  ELEVATE YOUR <br />
                  <span className="text-[#d9ff00]">IDENTITY.</span>
                </h1>
              </SlideIn>

              <FadeIn delay={0.4}>
                <p className="max-w-2xl text-lg md:text-xl text-white/60 mb-12">
                  Inspired by the velocity of Lando Norris. Upload your portrait and let our AI engine craft your high-performance branding profile in seconds.
                </p>
              </FadeIn>

              <FadeIn delay={0.6}>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="group relative cursor-pointer"
                >
                  <div className="absolute inset-0 bg-[#d9ff00] blur-xl opacity-20 group-hover:opacity-40 transition-opacity" />
                  <div className="relative border-2 border-[#d9ff00] p-1">
                    <div className="bg-[#d9ff00] text-black font-oswald text-2xl px-12 py-6 uppercase tracking-widest transition-transform group-hover:scale-[0.98]">
                      Analyze My Vibe
                    </div>
                  </div>
                </div>
              </FadeIn>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileUpload} 
                accept="image/*" 
                className="hidden" 
              />
            </motion.section>
          ) : loading ? (
            <motion.section 
              key="loading"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="flex flex-col items-center justify-center min-h-[70vh]"
            >
              <div className="relative w-24 h-24 mb-8">
                <motion.div 
                  animate={{ rotate: 360 }}
                  transition={{ repeat: Infinity, duration: 1, ease: "linear" }}
                  className="absolute inset-0 border-4 border-[#d9ff00]/20 border-t-[#d9ff00] rounded-full"
                />
              </div>
              <h2 className="font-oswald text-4xl uppercase tracking-tighter">Calibrating Performance...</h2>
              <p className="text-white/40 mt-2">Analyzing style vectors and brand alignment</p>
            </motion.section>
          ) : profile && (
            <motion.section 
              key="result"
              initial={{ opacity: 0, y: 50 }}
              animate={{ opacity: 1, y: 0 }}
              className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start"
            >
              {/* Image Side */}
              <div className="relative aspect-[4/5] overflow-hidden group">
                {previewImage && (
                  <img 
                    src={previewImage} 
                    alt="Preview" 
                    className="w-full h-full object-cover grayscale brightness-75 group-hover:grayscale-0 group-hover:brightness-100 transition-all duration-1000"
                  />
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-transparent to-transparent opacity-60" />
                <div className="absolute top-6 left-6 font-oswald text-4xl text-[#d9ff00] opacity-50">LN x YOU</div>
                <div className="absolute bottom-8 left-8">
                  <div className="flex gap-2">
                    {profile.brandAttributes.map((attr, i) => (
                      <span key={i} className="bg-white/10 backdrop-blur-md px-3 py-1 text-[10px] uppercase tracking-widest border border-white/20">
                        {attr}
                      </span>
                    ))}
                  </div>
                </div>
              </div>

              {/* Data Side */}
              <div className="flex flex-col gap-10">
                <FadeIn>
                  <div className="inline-block px-3 py-1 bg-[#d9ff00] text-black font-oswald text-xs uppercase tracking-widest mb-4">
                    Identity Verified
                  </div>
                  <h2 className="font-oswald text-7xl md:text-8xl uppercase tracking-tighter leading-none mb-4">
                    {profile.name}
                  </h2>
                  <p className="text-2xl md:text-3xl font-light text-[#d9ff00] tracking-wide uppercase italic">
                    "{profile.tagline}"
                  </p>
                </FadeIn>

                <div className="grid grid-cols-2 gap-8 py-10 border-y border-white/10">
                  <FadeIn delay={0.2}>
                    <h4 className="text-[10px] uppercase tracking-[0.3em] text-white/40 mb-2 font-bold">DNA Core</h4>
                    <p className="text-xl font-medium">{profile.personality}</p>
                  </FadeIn>
                  <FadeIn delay={0.3}>
                    <h4 className="text-[10px] uppercase tracking-[0.3em] text-white/40 mb-2 font-bold">Signature Aura</h4>
                    <div className="flex items-center gap-3">
                      <div className="w-6 h-6 rounded-full" style={{ backgroundColor: profile.primaryColor }} />
                      <p className="font-mono text-sm">{profile.primaryColor.toUpperCase()}</p>
                    </div>
                  </FadeIn>
                </div>

                <FadeIn delay={0.4}>
                  <p className="text-lg leading-relaxed text-white/60">
                    {profile.bio}
                  </p>
                </FadeIn>

                <FadeIn delay={0.5} className="flex gap-4">
                  <button className="flex-1 bg-white text-black font-oswald py-4 uppercase tracking-[0.2em] text-sm hover:bg-[#d9ff00] transition-colors">
                    Download Brand Kit
                  </button>
                  <button 
                    onClick={reset}
                    className="px-8 border border-white/20 hover:bg-white hover:text-black transition-colors font-oswald uppercase tracking-widest text-sm"
                  >
                    Redo
                  </button>
                </FadeIn>

                <div className="mt-8 pt-8 border-t border-white/5 flex gap-10 opacity-30">
                  <div className="flex flex-col">
                    <span className="text-[10px] uppercase mb-1">Project</span>
                    <span className="font-oswald text-lg">FAST-FORWARD_24</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[10px] uppercase mb-1">Status</span>
                    <span className="font-oswald text-lg">OPTIMIZED</span>
                  </div>
                </div>
              </div>
            </motion.section>
          )}
        </AnimatePresence>
      </main>

      {/* Social Links Footer - Fixed */}
      <footer className="fixed bottom-0 left-0 w-full z-50 p-6 flex justify-between items-end pointer-events-none">
        <div className="pointer-events-auto flex flex-col gap-4">
          {['IG', 'TW', 'YT'].map(social => (
            <a key={social} href="#" className="font-oswald text-sm hover:text-[#d9ff00] transition-colors">
              {social}
            </a>
          ))}
        </div>
        <div className="text-[10px] uppercase tracking-[0.4em] text-white/20 transform origin-right rotate-90 translate-x-1/2 -translate-y-12">
          Velocity Identity Engine v1.0
        </div>
      </footer>

      {error && (
        <div className="fixed top-24 right-6 z-[60] bg-red-500 text-white p-4 font-oswald uppercase tracking-widest text-sm shadow-xl animate-bounce">
          {error}
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence, useScroll, useTransform } from 'framer-motion';
import { BrandProfile } from './types';
import { analyzeBrandingFromImage } from './services/geminiService';
import { FadeIn, SlideIn } from './components/MotionWrapper';

const NEON_YELLOW = "#d9ff00";

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [profile, setProfile] = useState<BrandProfile | null>(null);
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const { scrollYProgress } = useScroll();
  const scaleProgress = useTransform(scrollYProgress, [0, 1], [1, 1.2]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setError(null);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setPreviewImage(base64);
      try {
        const result = await analyzeBrandingFromImage(base64);
        setProfile(result);
        window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      } catch (err) {
        setError("Erro na análise. Verifique a conexão.");
      } finally {
        setLoading(false);
      }
