import { GoogleGenAI, Type } from "@google/genai";
import { BrandProfile } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeBrandingFromImage = async (base64Image: string): Promise<BrandProfile> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image.split(',')[1] || base64Image,
            },
          },
          {
            text: "Analyze this portrait for high-performance marketing agency branding. Vibe: Lando Norris racing aesthetic, data-driven, fast, technical. Create a 'Target Identity' for this person as a business leader or top-tier creator. Return JSON: name (business persona), tagline (sales/growth focused), personality (3 technical personality traits), primaryColor (neon hex), brandAttributes (4 growth-focused keywords), and bio (professional, technical, edgy bio about their scaling potential).",
          },
        ],
      },
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          tagline: { type: Type.STRING },
          personality: { type: Type.STRING },
          primaryColor: { type: Type.STRING },
          brandAttributes: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
          },
          bio: { type: Type.STRING },
        },
        required: ["name", "tagline", "personality", "primaryColor", "brandAttributes", "bio"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text);
};

import { GoogleGenAI, Type } from "@google/genai";
import { BrandProfile } from "../types";

// Always initialize with the named parameter 'apiKey' and use process.env.API_KEY directly.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeBrandingFromImage = async (base64Image: string): Promise<BrandProfile> => {
  // Define image and text parts separately as per standard multi-modal usage.
  const imagePart = {
    inlineData: {
      mimeType: "image/jpeg",
      data: base64Image.split(',')[1] || base64Image,
    },
  };
  const textPart = {
    text: "Analyze this portrait for high-performance marketing agency branding. Vibe: Lando Norris racing aesthetic, data-driven, fast, technical. Create a 'Target Identity' for this person as a business leader or top-tier creator. Return JSON: name (business persona), tagline (sales/growth focused), personality (3 technical personality traits), primaryColor (neon hex), brandAttributes (4 growth-focused keywords), and bio (professional, technical, edgy bio about their scaling potential).",
  };

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [imagePart, textPart],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          tagline: { type: Type.STRING },
          personality: { type: Type.STRING },
          primaryColor: { type: Type.STRING },
          brandAttributes: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
          },
          bio: { type: Type.STRING },
        },
        required: ["name", "tagline", "personality", "primaryColor", "brandAttributes", "bio"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI telemetry engine.");
  return JSON.parse(text.trim());
};

