import { GoogleGenAI, Type } from "@google/genai";
import { BrandProfile } from "../types";

// Always initialize with the named parameter 'apiKey' and use process.env.API_KEY directly.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeBrandingFromImage = async (base64Image: string): Promise<BrandProfile> => {
  // Define image and text parts separately as per standard multi-modal usage.
  const imagePart = {
    inlineData: {
      mimeType: "image/jpeg",
      data: base64Image.split(',')[1] || base64Image,
    },
  };
  const textPart = {
    text: "Analyze this portrait for high-performance 'Omega Velocity' branding. Vibe: Advanced technical leadership, futuristic, high-IQ design, precise. The brand color is a vibrant Teal/Turquoise (#00cfc1). Create a 'Target Identity' for this person as a visionary founder or creative director. Return JSON: name (visionary persona), tagline (growth/velocity focused), personality (3 technical personality traits), primaryColor (always #00cfc1), brandAttributes (4 premium keywords), and bio (authoritative, technical bio highlighting their unique Omega-level scaling capability).",
  };

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [imagePart, textPart],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          tagline: { type: Type.STRING },
          personality: { type: Type.STRING },
          primaryColor: { type: Type.STRING },
          brandAttributes: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
          },
          bio: { type: Type.STRING },
        },
        required: ["name", "tagline", "personality", "primaryColor", "brandAttributes", "bio"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI telemetry engine.");
  return JSON.parse(text.trim());
};

