        style={{ rotateX: cameraTiltX, rotateY: cameraTiltY }}
        className="relative z-10 flex gap-20 px-[25vw] pb-20 overflow-x-visible transform-gpu"
      >
        {PORTFOLIO_VIDEOS.map((video, i) => (
          <PortfolioCard 
            key={video.id} 
            video={video} 
            index={i} 
            total={PORTFOLIO_VIDEOS.length}
            scrollProgress={currentCardIndex}
          />
        ))}
      </motion.div>

      {/* Bottom Technical HUD */}
      <div className="mt-20 px-10 flex flex-col md:flex-row justify-between items-center gap-10 opacity-40">
         <div className="flex gap-12 font-mono text-[8px] uppercase tracking-[0.4em]">
            <span>AF-C ACTIVE</span>
            <span>SHUTTER: ELECTRONIC</span>
            <span>GAMMA: LOG-C4</span>
         </div>
         <div className="flex items-center gap-4">
           <div className="w-32 h-[2px] bg-white/10 relative overflow-hidden">
             <motion.div 
               style={{ scaleX: scrollYProgress, originX: 0 }}
               className="absolute inset-0 bg-[#00cfc1]"
             />
           </div>
           <span className="font-mono text-[10px]">0{Math.round(PORTFOLIO_VIDEOS.length * 0.5)} / 0{PORTFOLIO_VIDEOS.length}</span>
         </div>
      </div>

      {/* Overlay Noise / Film Grain */}
      <div className="absolute inset-0 pointer-events-none opacity-[0.03] mix-blend-overlay bg-[url('https://grainy-gradients.vercel.app/noise.svg')]" />
