const PortfolioCard = ({ video, index, total, scrollProgress }: any) => {
  const cardRef = useRef(null);

  // Calcula a posição relativa (-1 a 1) baseada no scroll
  // Isso cria o efeito de "foco" quando o item está no centro
  const xRange = [index / total, (index + 0.5) / total, (index + 1) / total];

  const rotateY = useTransform(scrollProgress, [index - 1, index, index + 1], [45, 0, -45]);
  const z = useTransform(scrollProgress, [index - 1, index, index + 1], [-200, 100, -200]);
  const opacity = useTransform(scrollProgress, [index - 1, index, index + 1], [0.3, 1, 0.3]);
  const scale = useTransform(scrollProgress, [index - 0.5, index, index + 0.5], [0.8, 1.1, 0.8]);

  const springRotateY = useSpring(rotateY, { stiffness: 100, damping: 30 });
  const springZ = useSpring(z, { stiffness: 100, damping: 30 });
  const springScale = useSpring(scale, { stiffness: 100, damping: 30 });

  return (
    <motion.div
      ref={cardRef}
      style={{
        rotateY: springRotateY,
        z: springZ,
        opacity,
        scale: springScale,
        perspective: 1000,
      }}
      className="relative min-w-[300px] md:min-w-[450px] aspect-[9/16] shrink-0 group"
    >
      {/* Viewfinder UI / Camera HUD */}
      <div className="absolute inset-0 z-30 pointer-events-none p-6 flex flex-col justify-between overflow-hidden">
        <div className="flex justify-between items-start opacity-0 group-hover:opacity-100 transition-all duration-500">
          <div className="font-mono text-[8px] text-[#00cfc1] bg-black/40 p-2 backdrop-blur-sm border-l border-[#00cfc1]">
            REC [•] <br />
            ISO 400 <br />
            F2.8 1/60
          </div>
          <div className="text-[#00cfc1] font-oswald text-[10px] tracking-widest uppercase italic">
            CAM_0{index + 1}
          </div>
        </div>

        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-12 h-12 border border-[#00cfc1]/20 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all">
          <div className="w-1 h-1 bg-[#00cfc1] rounded-full animate-pulse" />
        </div>

        <div className="flex justify-between items-end opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
          <div>
            <div className="font-oswald text-4xl italic uppercase leading-[0.8] mb-2">{video.title}</div>
            <div className="text-[#00cfc1] text-[10px] font-mono tracking-widest">{video.category}</div>
          </div>
          <div className="w-10 h-10 border border-[#00cfc1] rounded-full flex items-center justify-center overflow-hidden">
             <motion.div 
               animate={{ scale: [1, 1.2, 1] }}
               transition={{ duration: 2, repeat: Infinity }}
               className="w-2 h-2 bg-[#00cfc1] rounded-full" 
             />
          </div>
        </div>
      </div>

      {/* Video Content */}
      <div className="absolute inset-0 bg-[#111] border border-white/5 overflow-hidden">
        <video 
          src={video.url} 
          muted 
          loop 
          playsInline
          autoPlay
          className="w-full h-full object-cover grayscale brightness-50 group-hover:grayscale-0 group-hover:brightness-100 transition-all duration-700"
        />
        {/* Optical Lens Flare FX */}
        <div className="absolute inset-0 bg-gradient-to-tr from-[#00cfc1]/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
