const PortfolioSection = () => {
  const sectionRef = useRef(null);
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start end", "end start"]
  });

  // Mapeia o progresso do scroll da seção para o índice dos cartões
  const currentCardIndex = useTransform(scrollYProgress, [0.1, 0.9], [0, PORTFOLIO_VIDEOS.length - 1]);

  // Mouse tracking para efeito de lente 3D global
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const handleMouseMove = (e: React.MouseEvent) => {
    const { clientX, clientY } = e;
    const { innerWidth, innerHeight } = window;
    mouseX.set((clientX / innerWidth) - 0.5);
    mouseY.set((clientY / innerHeight) - 0.5);
  };

  const cameraTiltX = useSpring(useTransform(mouseY, [-0.5, 0.5], [5, -5]));
  const cameraTiltY = useSpring(useTransform(mouseX, [-0.5, 0.5], [-10, 10]));

  return (
    <section 
      id="portfolio" 
      ref={sectionRef}
      onMouseMove={handleMouseMove}
      className="py-60 bg-[#050505] overflow-hidden select-none relative"
      style={{ perspective: "2000px" }}
    >
      <div className="px-10 mb-20 relative z-20">
        <SectionTitle title="The Motion Vault" subtitle="Camera & Optics Protocol" />
        <div className="flex justify-between items-end border-b border-white/5 pb-8">
          <p className="text-white/30 font-oswald text-[10px] tracking-[0.4em] uppercase">
            3D Lens Simulation — Arraste Verticalmente para navegar
          </p>
          <div className="flex gap-4 items-center">
            <span className="font-mono text-[8px] text-[#00cfc1] uppercase">Aperture: F1.4</span>
            <div className="w-12 h-px bg-[#00cfc1]/30" />
            <span className="font-mono text-[8px] text-[#00cfc1] animate-pulse">LENS_STABILIZER_ON</span>
          </div>
        </div>
      </div>

      {/* Global Camera Viewfinder Element */}
      <motion.div 
        style={{ rotateX: cameraTiltX, rotateY: cameraTiltY }}
        className="relative z-10 flex gap-20 px-[25vw] pb-20 overflow-x-visible transform-gpu"
      >
        {PORTFOLIO_VIDEOS.map((video, i) => (
          <PortfolioCard 
            key={video.id} 
            video={video} 
            index={i} 
            total={PORTFOLIO_VIDEOS.length}
            scrollProgress={currentCardIndex}
          />
        ))}
      </motion.div>

      {/* Bottom Technical HUD */}
      <div className="mt-20 px-10 flex flex-col md:flex-row justify-between items-center gap-10 opacity-40">
         <div className="flex gap-12 font-mono text-[8px] uppercase tracking-[0.4em]">
            <span>AF-C ACTIVE</span>
            <span>SHUTTER: ELECTRONIC</span>
            <span>GAMMA: LOG-C4</span>
         </div>
         <div className="flex items-center gap-4">
           <div className="w-32 h-[2px] bg-white/10 relative overflow-hidden">
             <motion.div 
               style={{ scaleX: scrollYProgress, originX: 0 }}
               className="absolute inset-0 bg-[#00cfc1]"
             />
           </div>
           <span className="font-mono text-[10px]">0{Math.round(PORTFOLIO_VIDEOS.length * 0.5)} / 0{PORTFOLIO_VIDEOS.length}</span>
         </div>
      </div>

      {/* Overlay Noise / Film Grain */}
      <div className="absolute inset-0 pointer-events-none opacity-[0.03] mix-blend-overlay bg-[url('https://grainy-gradients.vercel.app/noise.svg')]" />
    </section>
  );
};

