  // Strategy Transition Effect
  const strategyScroll = useScroll({
    target: strategyRef,
    offset: ["start start", "end start"]
  });

  const strategyScale = useTransform(strategyScroll.scrollYProgress, [0.7, 1], [1, 0.85]);
  const strategyOpacity = useTransform(strategyScroll.scrollYProgress, [0.7, 1], [1, 0]);
  const strategyBlur = useTransform(strategyScroll.scrollYProgress, [0.7, 1], ["blur(0px)", "blur(20px)"]);

  const heroTextY = useTransform(smoothProgress, [0, 0.2], [0, -150]);
  const heroSkew = useTransform(smoothProgress, [0, 0.2], [0, -5]);
  const bgOpacity = useTransform(smoothProgress, [0, 0.1], [1, 0.3]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setPreviewImage(base64);
      try {
        const result = await analyzeBrandingFromImage(base64);
        setProfile(result);
        document.getElementById('ai-result')?.scrollIntoView({ behavior: 'smooth' });
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

